from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 300, "גרף מהירות-זמן של רקטה: עלייה קווית ל-200 מטר לשנייה ב-10 שניות, ירידה קווית לאפס ב-30 שניות, ואחר כך ירידה איטית לערכים שליליים קטנים")
    X, Y = g.graph(70, 220, 420, 170, "t (s)", "v (m/s)", xticks=[(10, "10"), (20, "20"), (30, "30")], yticks=[(100, "100"), (200, "200")], xmax=45, ymin=-30, ymax=200)
    g.plot(X, Y, [(0, 0), (10, 200), (30, 0), (45, -0.75)])
    g.guide(X, Y, 10, 200)
    return g

def dyn(a_txt, Tsize, note):
    return lambda: fbd([("T", 90, Tsize), ("mg", -90, 1.0)], "תרשים כוחות על הגוף התלוי: כוח הדינמומטר T כלפי מעלה וכוח הכובד mg כלפי מטה. " + note, positive=90 if "up" in a_txt else -90, body="block", note=note)

E(id="bagrut-1984-q1", year=1984, label="1984 שאלה 1", topic="kinematics", sub="kin-graphs", diff=3, fig=fig,
  stem=r"רקטה לחקר מזג האוויר שוגרה אנכית כלפי מעלה. הגרף מתאר את מהירות הרקטה כפונקציה של הזמן. אפשר להזניח את התנגדות האוויר.",
  parts=[
    P("א", r"כעבור כמה שניות נגמר הדלק במנועי הרקטה? נמקו.", num(10, "s"), ["graph", "understanding"], [
        X(r"הכיוון החיובי נקבע לפי הגרף: בהתחלה הרקטה עולה והמהירות חיובית, ולכן כלפי מעלה חיובי. כל עוד המנוע דוחף, המהירות כלפי מעלה גדלה. ברגע שהדלק נגמר נשאר רק כוח הכובד, והמהירות מתחילה לקטון."),
        S(r"מחפשים את הנקודה שבה השיפוע מתהפך", r"השיפוע הוא התאוצה. עד עשר שניות הוא חיובי והמנוע דוחף, ואחר כך הוא שלילי ופועל רק כוח הכובד", r"t = 10\,\text{s}"),
        C(r"בדיקה: התאוצה אחרי הכיבוי", r"בלי מנוע ובלי התנגדות אוויר, התאוצה צריכה להיות תאוצת הנפילה החופשית, כלפי מטה", r"a = \frac{0 - 200}{30 - 10} = -10\,\text{m/s}^2 = -g \;\checkmark", eq=r"\bar a = \frac{\Delta v}{\Delta t}"),
    ], r"$10\,\text{s}$", key=r"10 s"),
    P("ב", r"כעבור כמה שניות הגיעה הרקטה לגובה המרבי? נמקו.", num(30, "s"), ["graph", "understanding"], [
        X(r"בגובה המרבי הרקטה מפסיקה לעלות. זה הרגע שבו המהירות מתאפסת ומחליפה כיוון."),
        S(r"מחפשים בגרף את הרגע שבו המהירות אפס", r"לפני הרגע הזה המהירות חיובית והרקטה עולה, ואחריו המהירות שלילית והיא יורדת", r"v(t) = 0 \;\Rightarrow\; t = 30\,\text{s}"),
    ], r"$30\,\text{s}$", key=r"30 s"),
    P("ג", r"לאיזה גובה עלתה הרקטה? נמקו.", num(3000, "m"), ["graph", "algebra"], [
        X(r"הגובה הוא השטח שמתחת לגרף מהירות-זמן, מתחילת התנועה עד רגע השיא."),
        S(r"שטח המשולש", r"בסיס המשולש הוא שלושים שניות, והגובה שלו הוא המהירות המרבית", r"H = \tfrac{1}{2} \cdot 30 \cdot 200 = 3000\,\text{m}"),
        C(r"בדיקה בדרך אחרת: שני חלקים בנפרד", r"משולש עד הכיבוי ועוד משולש מהכיבוי עד השיא", r"\tfrac{1}{2} \cdot 10 \cdot 200 + \tfrac{1}{2} \cdot 20 \cdot 200 = 1000 + 2000 = 3000\,\text{m} \;\checkmark"),
    ], r"$3000\,\text{m}$", key=r"3000 m"),
    P("ד", r"בגובה המרבי הופעל מנוע עזר, והרקטה ירדה ממנו בתאוצה קבועה של $0.05\,\text{m/s}^2$. כעבור כמה שניות מהשיגור חזרה הרקטה לקרקע?", num(376.41, "s"), ["principle", "algebra"], [
        X(r"מהשיא הרקטה יוצאת ממנוחה ויורדת שלושת אלפים מטר בתאוצה קבועה וקטנה. מוצאים את זמן הירידה, ומוסיפים את שלושים השניות עד השיא. לירידה בוחרים כלפי מטה כחיובי, כי זה כיוון התנועה והתאוצה."),
        S(r"משוואת המקום לירידה", r"הראשית בשיא, כלפי מטה חיובי. בשיא המהירות אפס, והתאוצה קבועה", r"3000 = 0 + 0 \cdot t_2 + \tfrac{1}{2} \cdot 0.05\,t_2^2", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"מבודדים את ריבוע הזמן", r"מכפילים בשתיים ומחלקים בתאוצה", r"t_2^2 = \frac{2 \cdot 3000}{0.05} = 120000"),
        S(r"מוציאים שורש", r"זמן הוא חיובי", r"t_2 = \sqrt{120000} \approx 346.4\,\text{s}"),
        S(r"מוסיפים את זמן העלייה", r"השאלה שואלת כמה זמן מהשיגור, ולא מהשיא", r"t = 30 + 346.4 = 376.4\,\text{s}"),
    ], r"$\approx 376.4\,\text{s}$", key=r"376.4 s"),
    P("ה", r"בתוך הרקטה תלוי על מאזני קפיץ (דינמומטר) גוף שמסתו $0.5\,\text{kg}$. מה מראה הדינמומטר: בעשר השניות הראשונות, בעשרים השניות שאחרי שהדלק נגמר, ובזמן הירידה עם מנוע העזר?", multi((r"בעשר השניות הראשונות", 15, "N"), (r"בעשרים השניות שאחרי שהדלק נגמר", 0, "N"), (r"בזמן הירידה עם מנוע העזר", 4.975, "N")), ["fbd", "signs", "principle", "algebra"], [
        X(r"הגוף נע יחד עם הרקטה, ולכן יש לו אותה תאוצה. על הגוף פועלים שני כוחות: הכובד כלפי מטה, והדינמומטר כלפי מעלה. הדינמומטר מראה את הכוח שהוא מפעיל. בכל שלב בונים משוואת כוחות לגוף."),
        D(r"שלב ראשון: תרשים הכוחות על הגוף (התאוצה כלפי מעלה)", dyn("up", 1.4, "תאוצה כלפי מעלה")),
        S(r"התאוצה בשלב הראשון", r"השיפוע של הקטע הראשון בגרף. הוא חיובי, כלומר התאוצה כלפי מעלה", r"a_1 = \frac{200 - 0}{10} = 20\,\text{m/s}^2", eq=r"\bar a = \frac{\Delta v}{\Delta t}"),
        S(r"משוואת כוחות, כלפי מעלה חיובי", r"בוחרים את כיוון התאוצה כחיובי. בכיוון החיובי פועל כוח הדינמומטר, ונגדו פועל הכובד", r"T_1 - mg = m a_1", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מבודדים את הכוח", r"מעבירים את הכובד לאגף השני ומוציאים את המסה כגורם משותף", r"T_1 = mg + ma_1 = m(g + a_1) = 0.5 \cdot (10 + 20) = 15\,\text{N}"),
        D(r"שלב שני: תרשים הכוחות על הגוף (נפילה חופשית)", lambda: fbd([("mg", -90, 1.0)], "תרשים כוחות על הגוף בנפילה חופשית: רק כוח הכובד כלפי מטה. הכיוון החיובי כלפי מעלה", positive=90, body="block", note="הדינמומטר לא מושך")),
        S(r"התאוצה בשלב השני", r"השיפוע מעשר עד שלושים שניות. הרקטה עדיין עולה, אבל מאטה", r"a_2 = \frac{0 - 200}{30 - 10} = -10\,\text{m/s}^2 = -g"),
        S(r"משוואת כוחות, כלפי מעלה חיובי", r"אותה משוואה כמו בשלב הראשון. התאוצה שלילית כי היא נגד הכיוון החיובי", r"T_2 - mg = m a_2 \;\Rightarrow\; T_2 = m(g + a_2) = 0.5 \cdot (10 - 10) = 0", eq=r"\Sigma\vec F = m\vec a"),
        D(r"שלב שלישי: תרשים הכוחות על הגוף (התאוצה כלפי מטה)", dyn("down", 0.9, "תאוצה קטנה כלפי מטה")),
        S(r"משוואת כוחות, כלפי מטה חיובי", r"בירידה התאוצה כלפי מטה, ולכן נוח לבחור את מטה כחיובי. בכיוון החיובי פועל הכובד, ונגדו פועל הדינמומטר", r"mg - T_3 = m a_3", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מבודדים ומציבים", r"מעבירים את הכוח לאגף אחד ומוציאים את המסה כגורם משותף", r"T_3 = m(g - a_3) = 0.5 \cdot (10 - 0.05) = 4.975\,\text{N}"),
    ], r"$15\,\text{N}$, אחר כך $0$ (חוסר משקל), ובירידה $4.975\,\text{N}$", key=r"15 N ; 0 ; 4.975 N"),
  ],
  concepts=["גרף מהירות-זמן", "שטח כהעתק", "נפילה חופשית", "חוסר משקל", "דינמומטר בגוף מאיץ"],
  summary=r"רקטה עם מנוע, ואחר כך בנפילה חופשית ובירידה מבוקרת: קריאת גרף, גובה וזמן, ומה מראה דינמומטר בכל שלב.",
  note=r"דינמומטר מראה את הכוח שהוא מפעיל, לא את המשקל. בנפילה חופשית הוא מראה אפס.",
  review="הנחה שלי.\nסעיף ה הוא סעיף אחד, כמו במקור, עם שלוש תיבות (מה מראה הדינמומטר בכל שלב).\nמה לבדוק: רק לאשר.")
